import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site.config";

/**
 * /robots.txt — generated by Next.js metadata route.
 * Allows all crawlers, disallows the admin panel and admin APIs,
 * and points to the sitemap (built from the SITE_URL env variable).
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: "*",
      allow: "/",
      disallow: ["/admin", "/api/"],
    },
    sitemap: `${SITE_URL}/sitemap.xml`,
  };
}
